    var SMALL = '600 11px system-ui, Roboto, sans-serif';
    var fitMins = function (t) { var m = Math.round((t - now) / 60000); return m < 1 ? 'Due' : String(m); };
    var widest = textWidth('Due');
    (buses || []).forEach(function (b) {
      var st = b.st || 'live';
