    var right = textWidth('Due');
    (rows || []).forEach(function (r) {
      if (!r.t || !r.t.length) return;
      var st = r.st || 'live';
      var pre = st === 'sched' ? '~' : '';
      var first = Math.round((r.t[0] - at.now) / 60000);
