    }
    var list = buses();
    if (!list.length) {
      L.innerHTML = '<span class="s">No buses</span>';
      R.innerHTML = '';
    } else {
      var b = list[idx];
      L.innerHTML = (data && data.l ? '<span class="sl">' + esc(data.l) + '</span>' : '') +
                    '<span class="b' + (b.idle ? ' idle' : '') + '">' + esc(b.k) + '</span><span class="d' + (b.st === 'sched' ? ' sched' : '') + '">' + esc(b.d) + '</span>';
