    try { Tasker.updateOverlayConfig({ width: String(totalFor(r)), configTransitionMs: 200, configTransitionEasing: 'EaseOut' }); }
    catch (e) { setRight(r); runTask('Bus Island', { busisland: 'fit' }); return; }
