function wifiName() {
  var raw = (typeof busssid === 'undefined' || String(busssid).charAt(0) === '%') ? '' : String(busssid);
  var name = raw.replace(/^"|"$/g, '').trim();
  return /^<unknown ssid>$|^0x$/i.test(name) ? '' : name;
