      if (off <= 45 && eta <= limit && st.d > 30 && (!best || (st.pref && !best.pref) || (st.pref === best.pref && eta < best.eta))) best = { id: st.id, n: st.n, d: st.d, eta: eta, pref: st.pref };
    });
